// INPUT:  Android locale and byte-aligned mbstate imports in a production ARM64 guest
// OUTPUT:  rudroid_locale_probe verifies thread locale, split UTF-8, bounds and restart contracts
// POS:    executes real conversions with caller-owned buffers and no native mbstate alias
typedef unsigned long Size;
typedef struct { unsigned char bytes[8]; } State;
typedef struct {
    char *decimal_point, *thousands_sep, *grouping, *int_curr_symbol, *currency_symbol;
    char *mon_decimal_point, *mon_thousands_sep, *mon_grouping, *positive_sign, *negative_sign;
    char digits[14];
} Lconv;
extern void *newlocale(int,const char *,void *);
extern void *duplocale(void *), *uselocale(void *);
extern void freelocale(void *);
extern char *setlocale(int,const char *);
extern Size __ctype_get_mb_cur_max(void);
extern Lconv *localeconv(void);
extern int *__errno(void), strcmp(const char *,const char *);
extern int mbsinit(const State *);
extern Size mbrtowc(unsigned *,const char *,Size,State *);
extern Size mbrlen(const char *,Size,State *);
extern Size wcrtomb(char *,unsigned,State *);
extern Size mbsnrtowcs(unsigned *,const char **,Size,Size,State *);
extern Size mbsrtowcs(unsigned *,const char **,Size,State *);
extern Size wcsnrtombs(char *,const unsigned **,Size,Size,State *);
extern int iswalpha_l(unsigned,void *), iswlower_l(unsigned,void *);
extern unsigned towlower_l(unsigned,void *);
extern int strcoll_l(const char *,const char *,void *);
extern long long strtoll_l(const char *,char **,int,void *);
extern long double strtold_l(const char *,char **,void *);
_Static_assert(sizeof(State)==8 && _Alignof(State)==1 && sizeof(Lconv)==96,"Android public layouts");
int rudroid_locale_probe(void) {
    const char *original=setlocale(0,0);
    void *old=uselocale(0);
    if (!original || !old) return 1;
    if (!setlocale(0,"C.UTF-8")) return 2;
    void *c=newlocale(0x1fbf,"C",0), *utf=newlocale(0x1fbf,"en_US.UTF-8",0);
    if (!c || !utf || c==utf) return 3;
    uselocale(c);
    if (__ctype_get_mb_cur_max()!=1) return 4;
    void *duplicate=duplocale(c);
    if (!duplicate || duplicate==c) return 5;
    uselocale(utf);
    if (__ctype_get_mb_cur_max()!=4 || !setlocale(0,"C") || __ctype_get_mb_cur_max()!=4) return 6;
    uselocale((void *)-1);
    if (__ctype_get_mb_cur_max()!=1) return 7;
    *__errno()=0;
    if (newlocale(0x40000000,"C",0) || *__errno()!=22) return 8;
    if (setlocale(0,"not-a-locale") || *__errno()!=2) return 9;
    if (strcmp(localeconv()->decimal_point,".") || strcmp(localeconv()->thousands_sep,"")) return 10;
    if (!iswalpha_l(0x4e2d,c) || !iswlower_l('a',utf) || towlower_l(0xc9,c)!=0xe9) return 11;
    if (strcoll_l("a","b",utf)>=0 || strtoll_l("123",0,10,c)!=123) return 12;
    union { long double value; Size bits[2]; } quad;
    quad.value=strtold_l("2.0",0,utf);
    if (quad.bits[0] || quad.bits[1]!=0x4000000000000000UL) return 13;
    struct { char before; State state; char after; } framed={.before=71,.state={{0,0,0,0,85,85,85,85}},.after=82};
    unsigned scalar=0;
    if (mbrtowc(&scalar,"\xf0",1,&framed.state)!=(Size)-2 || framed.state.bytes[0]!=0xf0) return 14;
    if (mbrlen("\x9f",1,&framed.state)!=(Size)-2) return 15;
    if (mbrtowc(&scalar,"\x8e\xae",2,&framed.state)!=2 || scalar!=0x1f3ae || !mbsinit(&framed.state)) return 16;
    if (framed.before!=71 || framed.after!=82 || framed.state.bytes[4]!=85 || framed.state.bytes[7]!=85) return 17;
    if (mbrtowc(&scalar,"\xc0\x80",2,&framed.state)!=(Size)-1 || *__errno()!=84 || !mbsinit(&framed.state)) return 18;
    if (mbrtowc(&scalar,"A",0,&framed.state)!=(Size)-2 || mbrtowc(&scalar,"A",1,&framed.state)!=1 || scalar!='A') return 19;
    framed.state.bytes[0]=0xf0;
    if (wcrtomb(0,0xffffffff,&framed.state)!=1 || !mbsinit(&framed.state)) return 20;
    const char *text="A\xe4\xb8\xad\xf0\x9f\x8e\xae", *cursor=text;
    if (mbsnrtowcs(0,&cursor,9,0,&framed.state)!=3 || cursor!=text) return 21;
    struct { unsigned before,out[4],after; } wide={.before=71,.after=82};
    if (mbsrtowcs(wide.out,&cursor,2,&framed.state)!=2 || wide.out[0]!='A' || wide.out[1]!=0x4e2d || cursor!=text+4) return 22;
    if (mbsrtowcs(wide.out+2,&cursor,2,&framed.state)!=1 || cursor || wide.out[2]!=0x1f3ae || wide.out[3]) return 23;
    if (wide.before!=71 || wide.after!=82) return 24;
    const unsigned *wcursor=wide.out;
    struct { char before,out[10],after; } narrow={.before=71,.after=82};
    if (wcsnrtombs(narrow.out,&wcursor,4,4,&framed.state)!=4 || wcursor!=wide.out+2) return 25;
    if (wcsnrtombs(narrow.out+4,&wcursor,2,6,&framed.state)!=4 || wcursor || strcmp(narrow.out,text)) return 26;
    if (narrow.before!=71 || narrow.after!=82) return 27;
    cursor="\xe4\xb8"; const char *incomplete=cursor;
    if (mbsnrtowcs(wide.out,&cursor,2,4,&framed.state)!=(Size)-1 || cursor!=incomplete+2 || *__errno()!=84 || !mbsinit(&framed.state)) return 28;
    uselocale(old);
    setlocale(0,original);
    freelocale(duplicate); freelocale(utf); freelocale(c);
    return 0;
}
